async function enableGitHubPages(options) {
	const { token, repoName } = options;
	const authHeader = {
		Authorization: `Bearer ${token.trim()}`,
		Accept: "application/vnd.github.v3+json",
		"Content-Type": "application/json"
	};
	const userRes = await fetch("https://api.github.com/user", { headers: authHeader });
	if (!userRes.ok) throw new Error("Не удалось проверить пользователя GitHub. Проверьте токен.");
	const owner = (await userRes.json()).login;
	const cleanRepo = repoName.replace(/^.*\//, "").trim();
	let res = await fetch(`https://api.github.com/repos/${owner}/${cleanRepo}/pages`, {
		method: "POST",
		headers: authHeader,
		body: JSON.stringify({ build_type: "workflow" })
	});
	if (!res.ok && res.status !== 409) res = await fetch(`https://api.github.com/repos/${owner}/${cleanRepo}/pages`, {
		method: "POST",
		headers: authHeader,
		body: JSON.stringify({ source: {
			branch: "main",
			path: "/"
		} })
	});
	const getRes = await fetch(`https://api.github.com/repos/${owner}/${cleanRepo}/pages`, { headers: authHeader });
	let pageUrl = `https://${owner}.github.io/${cleanRepo}/`;
	if (getRes.ok) {
		const pageData = await getRes.json();
		if (pageData.html_url) pageUrl = pageData.html_url;
	}
	return {
		pageUrl,
		owner
	};
}
